function lengthOfLongestSubstring(s) {
  const last = new Map();
  let left = 0, best = 0;
  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    if (last.has(ch) && last.get(ch) >= left) {
      left = Math.max(left, last.get(ch) + 1); // 防 left 回退
    }
    last.set(ch, right);
    best = Math.max(best, right - left + 1);
  }
  return best;
}
// lengthOfLongestSubstring('abba')  => 2 ('ab')
// lengthOfLongestSubstring('abcabcbb') => 3 ('abc')

function permute(nums) {
  const ans = [], path = [], used = new Array(nums.length).fill(false);
  const backtrack = () => {
    if (path.length === nums.length) {
      ans.push([...path]);      // 必须拷贝
      return;
    }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;
      used[i] = true; path.push(nums[i]);   // 做选择
      backtrack();                          // 递归
      path.pop(); used[i] = false;          // 撤销
    }
  };
  backtrack();
  return ans;
}

